namespace ghidra.app.plugin.core.decompile.actions;

using static ghidra.app.plugin.core.decompile.actions.PCodeCfgGraphTask.PcodeGraphSubType;

using docking.action;
using ghidra.app.plugin.core.decompile;
using ghidra.app.services;
using ghidra.app.util;
using ghidra.framework.options;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.pcode;
using ghidra.util;
using ghidra.util;
using ghidra.util.task;

public class PCodeCfgAction : AbstractDecompilerAction {

	public PCodeCfgAction() : base("Graph PCode Control Flow")
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ControlFlowGraph"));
		setMenuBarData(new MenuData(new string[] { "Graph Control Flow" }, "graph"));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		return context.getFunction() != null;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		PluginTool tool = context.getTool();
		GraphDisplayBroker service = tool.getService(typeof(GraphDisplayBroker));
		if (service == null) {
			Msg.showError(this, tool.getToolFrame(), "AST Graph Failed",
				"Graph consumer not found: Please add a graph consumer provider to your tool");
			return;
		}

		// TODO: Options should really be obtained from graph service
		Options options = tool.getOptions("Graph");
		bool reuseGraph = options.getBoolean("Reuse Graph", false);
		int codeLimitPerBlock = options.getInt("Max Code Lines Displayed", 10);
		HighFunction highFunction = context.getHighFunction();
		Address locationAddr = context.getLocation().getAddress();
		PCodeCfgGraphTask task =
			new PCodeCfgGraphTask(tool, service, !reuseGraph, codeLimitPerBlock,
				locationAddr, highFunction, CONTROL_FLOW_GRAPH);
		new TaskLauncher(task, tool.getToolFrame());
	}

}
